function aiGlow(x, y, r, col, a) { const S = AI_S; if (S.rot) { const c = Math.cos(S.rot), n = Math.sin(S.rot); [x, y] = [x * c - y * n, x * n + y * c]; } glow(x, y, r, col, a); }
